C     Powers: in line for a constant exponent from 1 to 8, in OTS$'s order,
C     each value used again computed once; by the OTS$ routines otherwise,
C     with INTEGER*2 values passed as longwords; COMPLEX always called.
      PROGRAM POWERS
      INTEGER I, N
      INTEGER*2 I2
      REAL X, Y, A(3)
      DOUBLE PRECISION D
      COMPLEX C
      COMPLEX*16 Z
      I = I**7
      I2 = I2**3 + I2**N
      X = (X + 1.0)**2 + A(I)**3
      Y = X**(-2) + X**Y + X**9
      D = D**8 + X**D
      C = C**2 + C**Y
      Z = Z**N
      END
